136	/**
137	 * Extends the {@code AbstractRequestInterceptorClient} class and provides an
138	 * implementation for federation of YARN RM and scaling an application across
139	 * multiple YARN SubClusters. All the federation specific implementation is
140	 * encapsulated in this class. This is always the last intercepter in the chain.
141	 */
142	public class FederationClientInterceptor
143	    extends AbstractClientRequestInterceptor {
144	
145	  /*
146	   * TODO YARN-6740 Federation Router (hiding multiple RMs for
147	   * ApplicationClientProtocol) phase 2.
148	   *
149	   * The current implementation finalized the main 4 calls (getNewApplication,
150	   * submitApplication, forceKillApplication and getApplicationReport). Those
151	   * allow us to execute applications E2E.
152	   */
153	
154	  private static final Logger LOG =
155	      LoggerFactory.getLogger(FederationClientInterceptor.class);
156	
157	  private int numSubmitRetries;
158	  private Map<SubClusterId, ApplicationClientProtocol> clientRMProxies;
159	  private FederationStateStoreFacade federationFacade;
160	  private Random rand;
161	  private RouterPolicyFacade policyFacade;
162	  private RouterMetrics routerMetrics;
163	  private ThreadPoolExecutor executorService;
164	  private final Clock clock = new MonotonicClock();
165	  private boolean returnPartialReport;
166	
167	  @Override
168	  public void init(String userName) {
169	    super.init(userName);
170	
171	    federationFacade = FederationStateStoreFacade.getInstance();
172	    rand = new Random(System.currentTimeMillis());
173	
174	
175	    int numThreads = getConf().getInt(
176	        YarnConfiguration.ROUTER_USER_CLIENT_THREADS_SIZE,
177	        YarnConfiguration.DEFAULT_ROUTER_USER_CLIENT_THREADS_SIZE);
178	    ThreadFactory threadFactory = new ThreadFactoryBuilder()
179	        .setNameFormat("RPC Router Client-" + userName + "-%d ").build();
180	
181	    BlockingQueue workQueue = new LinkedBlockingQueue<>();
182	    this.executorService = new ThreadPoolExecutor(numThreads, numThreads,
183	        0L, TimeUnit.MILLISECONDS, workQueue, threadFactory);
184	
185	    final Configuration conf = this.getConf();
186	
187	    try {
188	      policyFacade = new RouterPolicyFacade(conf, federationFacade,
189	          this.federationFacade.getSubClusterResolver(), null);
190	    } catch (FederationPolicyInitializationException e) {
191	      LOG.error(e.getMessage());
192	    }
193	
194	    numSubmitRetries =
195	        conf.getInt(YarnConfiguration.ROUTER_CLIENTRM_SUBMIT_RETRY,
196	            YarnConfiguration.DEFAULT_ROUTER_CLIENTRM_SUBMIT_RETRY);
197	
198	    clientRMProxies =
199	        new ConcurrentHashMap<SubClusterId, ApplicationClientProtocol>();
200	    routerMetrics = RouterMetrics.getMetrics();
201	
202	    returnPartialReport = conf.getBoolean(
203	        YarnConfiguration.ROUTER_CLIENTRM_PARTIAL_RESULTS_ENABLED,
204	        YarnConfiguration.DEFAULT_ROUTER_CLIENTRM_PARTIAL_RESULTS_ENABLED);
205	  }
206	
207	  @Override
208	  public void setNextInterceptor(ClientRequestInterceptor next) {
209	    throw new YarnRuntimeException("setNextInterceptor is being called on "
210	        + "FederationClientRequestInterceptor, which should be the last one "
211	        + "in the chain. Check if the interceptor pipeline configuration "
212	        + "is correct");
213	  }
214	
215	  @VisibleForTesting
216	  protected ApplicationClientProtocol getClientRMProxyForSubCluster(
217	      SubClusterId subClusterId) throws YarnException {
218	
219	    if (clientRMProxies.containsKey(subClusterId)) {
220	      return clientRMProxies.get(subClusterId);
221	    }
222	
223	    ApplicationClientProtocol clientRMProxy = null;
224	    try {
225	      boolean serviceAuthEnabled = getConf().getBoolean(
226	              CommonConfigurationKeys.HADOOP_SECURITY_AUTHORIZATION, false);
227	      UserGroupInformation realUser = user;
228	      if (serviceAuthEnabled) {
229	        realUser = UserGroupInformation.createProxyUser(
230	                user.getShortUserName(), UserGroupInformation.getLoginUser());
231	      }
232	      clientRMProxy = FederationProxyProviderUtil.createRMProxy(getConf(),
233	          ApplicationClientProtocol.class, subClusterId, realUser);
234	    } catch (Exception e) {
235	      RouterServerUtil.logAndThrowException(
236	          "Unable to create the interface to reach the SubCluster "
237	              + subClusterId,
238	          e);
239	    }
240	
241	    clientRMProxies.put(subClusterId, clientRMProxy);
242	    return clientRMProxy;
243	  }
244	
245	  private SubClusterId getRandomActiveSubCluster(
246	      Map<SubClusterId, SubClusterInfo> activeSubclusters)
247	      throws YarnException {
248	
249	    if (activeSubclusters == null || activeSubclusters.size() < 1) {
250	      RouterServerUtil.logAndThrowException(
251	          FederationPolicyUtils.NO_ACTIVE_SUBCLUSTER_AVAILABLE, null);
252	    }
253	    List<SubClusterId> list = new ArrayList<>(activeSubclusters.keySet());
254	
